}

@layer base {
  html,
  body {
    height: 100%;
  }

  body {
    margin: 0;
    background: var(--window);
    color: var(--ink);
    font-family: var(--font-sans);
    scrollbar-width: thin;
    scrollbar-color: var(--scroll) transparent;
  }

  h1,
  h2,
  h3,
  h4 {
    font-family: var(--font-display);
  }

  button:not(:disabled) {
    cursor: pointer;
  }
}

/* The buttons and fields the prototypes repeat on every screen. */
@layer components {
  .main-button {
    @apply inline-flex items-center justify-center gap-2 rounded-full bg-coal px-5 py-2.5 font-display font-medium text-white disabled:opacity-35;
  }

  .pill-button {
    @apply inline-flex items-center gap-1.5 rounded-full border-[1.5px] border-line bg-transparent px-3.5 py-[7px] text-sm text-ink disabled:opacity-35;
  }

  /* Inherits its colour because it sits on cards that stay light in dark mode and on the themed page alike. */
  .pill-ghost {
    @apply border-transparent text-[inherit];

    &:hover:not(:disabled) {
      background-color: color-mix(in srgb, currentColor 12%, transparent);
    }
  }

  .pill-dark {
    @apply border-active bg-active text-active-ink;
  }
